INSERT INTO feature VALUES('artifact-store','storage','Kernel artifacts on the record and value planes',NULL,'implemented','uncommon','mainstream languages','A kernel artifact is stored one value leaf per distinct declaration segment, keyed by the identity of that leaf, beside an order that is a chain of content-defined chunks, each under a key of its own, naming each declaration by its record''s key and, in an artifact a store keeps, by the kernel''s content key of its entry, so an insertion leaves every record whose bytes it does not change and rewrites only the chunks of the order it touches; a segment opens with its table of names, and a node that reads a constant writes the entry of the constant''s key when the export holds a key for each place, so the insertion leaves each segment that reads no subterm past it; an artifact is named whole or cut from bytes alone, and its manifest says which; or it commits through the value plane as one value whose declaration segments each hold the one before, so an edit to a declaration shares every chunk before it; either is read back through the kernel''s decoder.','storage-artifact kernel-term','crates/storage-artifact/tests/artifact_contract.rs',NULL,'#3225');
